// src/Component/UserList.js
import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  fetchUsersAsync,
  createUserAsync,
  updateUserAsync,
  deleteUserAsync,
  selectUsersState,
} from "./userSlice";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "./UserList.css";
import axios from "axios";

function UserList() {
  const dispatch = useDispatch();
  const { users, loading, error } = useSelector(selectUsersState);

  const [editUserId, setEditUserId] = useState(null);
  const [editData, setEditData] = useState({});
  const [showAddForm, setShowAddForm] = useState(false);
  const [newUser, setNewUser] = useState({
    username: "",
    email: "",
    first_name: "",
    last_name: "",
    profile: { bio: "", phone: "" },
    is_active: true,
  });

  // Pagination
  const [currentPage, setCurrentPage] = useState(1);
  const usersPerPage = 5;

  useEffect(() => {
    dispatch(fetchUsersAsync());
  }, [dispatch]);

  const handleChange = (key, value, isEdit = false) => {
    if (key === "bio" || key === "phone") {
      isEdit
        ? setEditData({ ...editData, profile: { ...editData.profile, [key]: value } })
        : setNewUser({ ...newUser, profile: { ...newUser.profile, [key]: value } });
    } else if (key === "is_active") {
      isEdit
        ? setEditData({ ...editData, [key]: value })
        : setNewUser({ ...newUser, [key]: value });
    } else {
      isEdit
        ? setEditData({ ...editData, [key]: value })
        : setNewUser({ ...newUser, [key]: value });
    }
  };

  // Save edited user
  const handleSave = async () => {
    if (!editUserId) return;
    try {
      await dispatch(updateUserAsync(editData)).unwrap();
      await dispatch(fetchUsersAsync());
      setEditUserId(null);

      // ✅ Toast message after save
      toast.success("✅ User updated successfully!", {
        position: "top-right",
        autoClose: 3000,
      });
    } catch (err) {
      console.error(err);
      toast.error(`❌ Update failed: ${err?.detail || JSON.stringify(err)}`, {
        position: "top-right",
        autoClose: 4000,
      });
    }
  };

  // Add new user
  const handleAddUser = async () => {
    try {
      await dispatch(createUserAsync(newUser)).unwrap();
      await dispatch(fetchUsersAsync());
      setShowAddForm(false);
      setNewUser({
        username: "",
        email: "",
        first_name: "",
        last_name: "",
        profile: { bio: "", phone: "" },
        is_active: true,
      });
      setCurrentPage(1);

      toast.success("✅ User created successfully!", {
        position: "top-right",
        autoClose: 3000,
      });
    } catch (err) {
      console.error(err);
      toast.error(`❌ Create failed: ${err?.detail || JSON.stringify(err)}`, {
        position: "top-right",
        autoClose: 4000,
      });
    }
  };

  // Delete user
  const handleDelete = async (id) => {
    if (!id) return;
    if (window.confirm("Are you sure you want to delete this user?")) {
      try {
        await dispatch(deleteUserAsync(id)).unwrap();
        await dispatch(fetchUsersAsync());
        toast.success("✅ User deleted successfully!", {
          position: "top-right",
          autoClose: 3000,
        });
      } catch (err) {
        console.error(err);
        toast.error(`❌ Delete failed: ${err?.detail || JSON.stringify(err)}`, {
          position: "top-right",
          autoClose: 4000,
        });
      }
    }
  };

  // Export all users
  const handleExportAll = async () => {
    const confirmDownload = window.confirm("Do you want to download all users as Excel?");
    if (!confirmDownload) return;

    try {
      const token = localStorage.getItem("token");
      const response = await axios.get("http://localhost:8000/api/export-users/", {
        headers: { Authorization: `Bearer ${token}` },
        responseType: "blob",
      });

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", "All_Users_Report.xlsx");
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);

      toast.success("✅ Exported all users successfully!", {
        position: "top-right",
        autoClose: 3000,
      });
    } catch (err) {
      toast.error("❌ Error downloading file: " + (err.response?.statusText || err.message), {
        position: "top-right",
        autoClose: 4000,
      });
    }
  };

  const sortedUsers = [...users].sort((a, b) => b.id - a.id);
  const totalPages = Math.ceil(sortedUsers.length / usersPerPage);
  const indexOfLastUser = currentPage * usersPerPage;
  const indexOfFirstUser = indexOfLastUser - usersPerPage;
  const currentUsers = sortedUsers.slice(indexOfFirstUser, indexOfLastUser);

  if (loading) return <p>Loading users...</p>;
  if (error)
    return (
      <p style={{ color: "red" }}>
        Error: {typeof error === "string" ? error : error.detail || JSON.stringify(error)}
      </p>
    );

  return (
    <div className="userlist-container">
      {/* ✅ Toast Container */}
      <ToastContainer />

      <h2>User Management</h2>
      {/* Buttons */}
      <div className="button-group">
        <button className="add-user-btn" onClick={() => setShowAddForm((prev) => !prev)}>
          {showAddForm ? "Cancel" : "Add User"}
        </button>
        <button className="export-all-btn" onClick={handleExportAll}>
          Export All Users
        </button>
      </div>

      {/* Add User Form */}
      {showAddForm && (
        <div className="add-user-form">
          <input
            placeholder="Username"
            value={newUser.username}
            onChange={(e) => handleChange("username", e.target.value)}
          />
          <input
            placeholder="Email"
            value={newUser.email}
            onChange={(e) => handleChange("email", e.target.value)}
          />
          <input
            placeholder="First Name"
            value={newUser.first_name}
            onChange={(e) => handleChange("first_name", e.target.value)}
          />
          <input
            placeholder="Last Name"
            value={newUser.last_name}
            onChange={(e) => handleChange("last_name", e.target.value)}
          />
          <input
            placeholder="Bio"
            value={newUser.profile.bio}
            onChange={(e) => handleChange("bio", e.target.value)}
          />
          <input
            placeholder="Phone"
            value={newUser.profile.phone}
            onChange={(e) => handleChange("phone", e.target.value)}
          />
          <select
            value={newUser.is_active ? "Active" : "Inactive"}
            onChange={(e) => handleChange("is_active", e.target.value === "Active")}
          >
            <option>Active</option>
            <option>Inactive</option>
          </select>
          <button className="save-btn" onClick={handleAddUser}>
            Save
          </button>
        </div>
      )}

      {/* User Table */}
      {/* ... your existing table code ... */}
    </div>
  );
}

export default UserList;
